//! XMSS^MT — RFC 8391 §4.2, parameter set XMSSMT-SHA2_20/2_256 (OID 0x00000001 in the
//! XMSS^MT registry): n=32, w=16, h=20, d=2 (two layers of h'=10 subtrees) -> 2^20 signatures.
//! Validated against vectors generated by the RFC companion xmss-reference (commit 171ccbd).
//! Like the reference, the very last index (2^20 - 1) is NOT used.
use std::collections::HashMap;

use crate::adrs::{to_byte_n, Adrs, TYPE_HASHTREE, TYPE_LTREE, TYPE_OTS};
use crate::hash::{h, h_msg, prf, prf_adrs, xor_n};
use crate::params::{LEN, N, NBytes};
use crate::wots::{self, WotsPk, WotsSig};
use crate::xmss::XmssError;

pub const MT_OID: u32 = 0x0000_0001;
pub const PARAM_NAME_MT: &str = "XMSSMT-SHA2_20/2_256";
pub const D: usize = 2;
pub const TREE_H: usize = 10;
pub const FULL_H: usize = 20;
pub const MT_INDEX_BYTES: usize = 3; // ceil(20/8)
pub const MT_SIG_BYTES: usize = MT_INDEX_BYTES + N + D * (LEN * N + TREE_H * N); // 4963
pub const MT_PK_BYTES: usize = 2 * N;
/// Usable signatures: 0 ..= 2^20 - 2 (reference marks 2^20-1 as exhausted).
pub const MT_LIMIT: u64 = (1u64 << FULL_H) - 1;

#[derive(Clone)]
pub struct MtSk { pub sk_seed: NBytes, pub sk_prf: NBytes, pub pub_seed: NBytes, pub root: NBytes }
#[derive(Clone, Debug, PartialEq)]
pub struct MtPk { pub root: NBytes, pub pub_seed: NBytes }
#[derive(Clone)]
pub struct MtSig { pub idx: u64, pub randomness: NBytes, pub layers: Vec<(WotsSig, [NBytes; TREE_H])> }

fn sub_adrs(layer: u32, tree: u64, t: u32) -> Adrs {
    let mut a = Adrs::new(); a.set_layer(layer); a.set_tree(tree); a.set_type(t); a
}
fn rand_hash(l: &NBytes, r: &NBytes, seed: &NBytes, adrs: &mut Adrs) -> NBytes {
    adrs.set_key_and_mask(0); let key = prf_adrs(seed, adrs);
    adrs.set_key_and_mask(1); let b0 = prf_adrs(seed, adrs);
    adrs.set_key_and_mask(2); let b1 = prf_adrs(seed, adrs);
    h(&key, &xor_n(l, &b0), &xor_n(r, &b1))
}
fn ltree(pk: &WotsPk, seed: &NBytes, layer: u32, tree: u64, leaf: u32) -> NBytes {
    let mut nodes: Vec<NBytes> = pk.to_vec();
    let mut adrs = sub_adrs(layer, tree, TYPE_LTREE);
    adrs.set_ltree_address(leaf);
    let mut height = 0u32;
    while nodes.len() > 1 {
        adrs.set_tree_height(height);
        let mut next = Vec::with_capacity(nodes.len() / 2 + 1);
        let mut i = 0;
        while i + 1 < nodes.len() { adrs.set_tree_index((i / 2) as u32); next.push(rand_hash(&nodes[i], &nodes[i + 1], seed, &mut adrs)); i += 2; }
        if i < nodes.len() { next.push(nodes[i]); }
        nodes = next; height += 1;
    }
    nodes[0]
}
fn ots_adrs(layer: u32, tree: u64, leaf: u32) -> Adrs { let mut a = sub_adrs(layer, tree, TYPE_OTS); a.set_ots_address(leaf); a }

/// All levels of subtree (layer, tree).
#[derive(Clone)]
pub struct Subtree { levels: Vec<Vec<NBytes>> }
impl Subtree {
    pub fn build(sk: &MtSk, layer: u32, tree: u64) -> Self {
        let leaves: Vec<NBytes> = (0..(1u32 << TREE_H)).map(|i| {
            let wsk = wots::expand_sk_adrs(&sk.sk_seed, &sk.pub_seed, &mut ots_adrs(layer, tree, i));
            let wpk = wots::pk_from_sk_adrs(&wsk, &sk.pub_seed, &mut ots_adrs(layer, tree, i));
            ltree(&wpk, &sk.pub_seed, layer, tree, i)
        }).collect();
        let mut levels = vec![leaves];
        let mut adrs = sub_adrs(layer, tree, TYPE_HASHTREE);
        for height in 0..TREE_H {
            adrs.set_tree_height(height as u32);
            let prev = &levels[height];
            let next: Vec<NBytes> = (0..prev.len() / 2).map(|i| { adrs.set_tree_index(i as u32); rand_hash(&prev[2 * i], &prev[2 * i + 1], &sk.pub_seed, &mut adrs) }).collect();
            levels.push(next);
        }
        Subtree { levels }
    }
    pub fn root(&self) -> NBytes { self.levels[TREE_H][0] }
    pub fn auth(&self, leaf: u32) -> [NBytes; TREE_H] {
        let mut a = [[0u8; N]; TREE_H];
        for (hh, x) in a.iter_mut().enumerate() { *x = self.levels[hh][((leaf >> hh) ^ 1) as usize]; }
        a
    }
}

pub fn mt_keygen_from_seed(sk_seed: NBytes, sk_prf: NBytes, pub_seed: NBytes) -> (MtSk, MtPk) {
    let mut sk = MtSk { sk_seed, sk_prf, pub_seed, root: [0u8; N] };
    sk.root = Subtree::build(&sk, (D - 1) as u32, 0).root();
    (sk.clone(), MtPk { root: sk.root, pub_seed })
}
pub fn mt_keygen() -> (MtSk, MtPk) {
    use rand::RngCore;
    let mut s = [[0u8; N]; 3];
    for x in s.iter_mut() { rand::rngs::OsRng.fill_bytes(x); }
    mt_keygen_from_seed(s[0], s[1], s[2])
}

/// Subtree cache for signing (public nodes only).
#[derive(Default)]
pub struct MtCache { trees: HashMap<(u32, u64), Subtree> }
impl MtCache {
    fn get(&mut self, sk: &MtSk, layer: u32, tree: u64) -> &Subtree {
        if self.trees.len() > 8 { self.trees.retain(|(l, _), _| *l == (D - 1) as u32); }
        self.trees.entry((layer, tree)).or_insert_with(|| Subtree::build(sk, layer, tree))
    }
}

pub(crate) fn mt_sign_at(sk: &MtSk, cache: &mut MtCache, idx: u64, msg: &[u8]) -> Result<MtSig, XmssError> {
    if idx >= MT_LIMIT { return Err(XmssError::NoLeaves); }
    let r = prf(&sk.sk_prf, &to_byte_n(idx));
    let mut key = [0u8; 3 * N];
    key[..N].copy_from_slice(&r); key[N..2 * N].copy_from_slice(&sk.root); key[2 * N..].copy_from_slice(&to_byte_n(idx));
    let mut m = h_msg(&key, msg);
    let mut tree = idx >> TREE_H;
    let mut leaf = (idx & ((1 << TREE_H) - 1)) as u32;
    let mut layers = Vec::with_capacity(D);
    for layer in 0..D as u32 {
        let wsk = wots::expand_sk_adrs(&sk.sk_seed, &sk.pub_seed, &mut ots_adrs(layer, tree, leaf));
        let ws = wots::sign_adrs(&wsk, &m, &sk.pub_seed, &mut ots_adrs(layer, tree, leaf));
        let st = cache.get(sk, layer, tree);
        layers.push((ws, st.auth(leaf)));
        m = st.root();
        leaf = (tree & ((1 << TREE_H) - 1)) as u32;
        tree >>= TREE_H;
    }
    Ok(MtSig { idx, randomness: r, layers })
}

pub fn mt_verify(pk: &MtPk, msg: &[u8], sig: &MtSig) -> bool {
    if sig.idx >= MT_LIMIT || sig.layers.len() != D { return false; }
    let mut key = [0u8; 3 * N];
    key[..N].copy_from_slice(&sig.randomness); key[N..2 * N].copy_from_slice(&pk.root); key[2 * N..].copy_from_slice(&to_byte_n(sig.idx));
    let mut node = h_msg(&key, msg);
    let mut tree = sig.idx >> TREE_H;
    let mut leaf = (sig.idx & ((1 << TREE_H) - 1)) as u32;
    for layer in 0..D as u32 {
        let (ws, auth) = &sig.layers[layer as usize];
        let wpk = wots::pk_from_sig_adrs(ws, &node, &pk.pub_seed, &mut ots_adrs(layer, tree, leaf));
        let mut n = ltree(&wpk, &pk.pub_seed, layer, tree, leaf);
        let mut adrs = sub_adrs(layer, tree, TYPE_HASHTREE);
        let mut i = leaf;
        for (hh, a) in auth.iter().enumerate() {
            adrs.set_tree_height(hh as u32); adrs.set_tree_index(i >> 1);
            n = if i & 1 == 0 { rand_hash(&n, a, &pk.pub_seed, &mut adrs) } else { rand_hash(a, &n, &pk.pub_seed, &mut adrs) };
            i >>= 1;
        }
        node = n;
        leaf = (tree & ((1 << TREE_H) - 1)) as u32;
        tree >>= TREE_H;
    }
    node == pk.root
}

impl MtPk {
    pub fn to_bytes(&self) -> [u8; MT_PK_BYTES] { let mut o = [0u8; MT_PK_BYTES]; o[..N].copy_from_slice(&self.root); o[N..].copy_from_slice(&self.pub_seed); o }
    pub fn from_bytes(b: &[u8]) -> Result<Self, XmssError> {
        if b.len() != MT_PK_BYTES { return Err(XmssError::BadPkLen); }
        Ok(MtPk { root: b[..N].try_into().unwrap(), pub_seed: b[N..].try_into().unwrap() })
    }
}
impl MtSig {
    /// RFC 8391 / reference layout: idx(3 BE) || r || (WOTS sig || auth) per layer, bottom first.
    pub fn to_bytes(&self) -> Vec<u8> {
        let mut v = Vec::with_capacity(MT_SIG_BYTES);
        v.extend_from_slice(&self.idx.to_be_bytes()[8 - MT_INDEX_BYTES..]);
        v.extend_from_slice(&self.randomness);
        for (w, a) in &self.layers { for x in w { v.extend_from_slice(x); } for x in a { v.extend_from_slice(x); } }
        v
    }
    pub fn from_bytes(b: &[u8]) -> Result<Self, XmssError> {
        if b.len() != MT_SIG_BYTES { return Err(XmssError::BadSigLen); }
        let mut ib = [0u8; 8]; ib[8 - MT_INDEX_BYTES..].copy_from_slice(&b[..MT_INDEX_BYTES]);
        let idx = u64::from_be_bytes(ib);
        let randomness: NBytes = b[MT_INDEX_BYTES..MT_INDEX_BYTES + N].try_into().unwrap();
        let mut off = MT_INDEX_BYTES + N;
        let mut layers = Vec::with_capacity(D);
        for _ in 0..D {
            let mut w = [[0u8; N]; LEN]; for x in w.iter_mut() { x.copy_from_slice(&b[off..off + N]); off += N; }
            let mut a = [[0u8; N]; TREE_H]; for x in a.iter_mut() { x.copy_from_slice(&b[off..off + N]); off += N; }
            layers.push((w, a));
        }
        Ok(MtSig { idx, randomness, layers })
    }
}
